import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, DatePicker, Flex, Select } from 'antd';

import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, useDateFilters, useFilters } from 'features/Filters';
import { useChannelOptions } from 'shared/hooks';
import { InputClearIcon } from 'shared/ui';

interface ITransactionsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const TransactionsFilters: FC<ITransactionsFiltersProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const dateFromKey = EFilters.ACTION_DATE_FROM;
	const dateToKey = EFilters.ACTION_DATE_TO;
	const { dateAfter, dateBefore, onDatesChange } = useDateFilters(dateFromKey, dateToKey);
	const { onFilterChange, getFilterValue } = useFilters();

	const { channelOptions, isFetching } = useChannelOptions();

	const transactionTypeFilter = [
		{ label: t('Списания'), value: 'deduction' },
		{ label: t('Поступления'), value: 'replenishment' },
	];

	return (
		<Flex gap={12} vertical {...props} className={className}>
			<DatePicker.RangePicker
				size="large"
				format="DD.MM.YYYY"
				value={[dateAfter, dateBefore]}
				style={{ minWidth: 230 }}
				onChange={(value) => {
					onDatesChange(value, [dateFromKey, dateToKey], true);
				}}
				placeholder={['Начало периода', 'Конец периода']}
			/>
			<Select
				value={getFilterValue(EFilters.CHANNEL) || t('Все каналы и группы')}
				options={channelOptions}
				onChange={(value) => onFilterChange(EFilters.CHANNEL, value)}
				placeholder={t('Выберите каналы')}
				size="large"
				showSearch
				optionFilterProp="search"
				allowClear={getFilterValue(EFilters.CHANNEL) ? { clearIcon: <InputClearIcon /> } : false}
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				style={{ width: '100%' }}
				loading={isFetching}
				disabled={isFetching}
			/>
			<Flex gap={8}>
				{transactionTypeFilter.map((type) => (
					<Button
						key={type.value}
						onClick={() =>
							onFilterChange(EFilters.TYPE, getFilterValue(EFilters.TYPE) === type.value ? null : type.value)
						}
						color="primary"
						variant={getFilterValue(EFilters.TYPE) === type.value ? 'solid' : 'outlined'}
						shape="round"
						block>
						{type.label}
					</Button>
				))}
			</Flex>
		</Flex>
	);
};
