import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import { useChannelsListQuery } from 'entities/Channel';
import { useReportsBalanceTransactionsListQuery } from 'entities/Transaction';
import { CHANNELS_LIMIT, EFilters, getUrlParamsForApi, TransactionsFilters, useFilters } from 'features/Filters';
import { EPaginationParams, Pagination } from 'features/Pagination';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { ButtonStyleLink, NoResults, OverlayLoader } from 'shared/ui';
import { formatDate, formatNumber, sendYmEvent } from 'shared/utils';

import styles from './TransactionList.module.scss';

interface ITransactionListProps extends HTMLAttributes<HTMLDivElement> {}

export const TransactionList: FC<ITransactionListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [searchParams] = useSearchParams();
	const { data, isFetching, isLoading } = useReportsBalanceTransactionsListQuery(getUrlParamsForApi(searchParams));
	const { data: channelList } = useChannelsListQuery({ [EPaginationParams.LIMIT]: CHANNELS_LIMIT });

	const { getFiltersCount } = useFilters();
	const hasFilters = getFiltersCount([EFilters.CHANNEL, EFilters.ACTION_DATE_FROM, EFilters.ACTION_DATE_TO]) > 0;
	const hasChannels = !!channelList?.results.length;

	return (
		<div {...props} className={cn(className, styles.transactionList)}>
			{isFetching && <OverlayLoader />}
			<Typography.Title level={5}>{t('История')}</Typography.Title>
			<TransactionsFilters className={styles.transactionList__filters} />
			<Flex vertical gap={4}>
				{data?.results.map((item) => (
					<Flex vertical className={styles.transactionList__card} key={item.created_at}>
						<Flex justify="space-between" align="center" gap={8} className={styles.transactionList__topCard}>
							<Typography.Text type="secondary">{formatDate(new Date(item.created_at), 'medium')}</Typography.Text>
							<Typography.Title style={{ margin: 0 }} level={5} type="success">
								{formatNumber(item.amount)} ${item.currency}
							</Typography.Title>
						</Flex>
						<Flex gap={8} className={styles.transactionList__bottomCard} justify="space-between">
							<Typography.Text strong ellipsis>
								{item.offer?.name}
							</Typography.Text>
						</Flex>
					</Flex>
				))}
			</Flex>
			{!isLoading && !data?.results.length && (
				<NoResults
					subtext={
						!hasChannels
							? t(
									'К сожалению, пока тут ничего. Для размещения постов, пожалуйста, добавьте свой первый канал или группу',
								)
							: hasFilters
								? t('Нет результатов для этого поискового запроса')
								: t('К сожалению, пока тут ничего. Размещайте посты и получайте выплаты')
					}
					goTo={
						<ButtonStyleLink
							size="large"
							to={hasChannels ? `/${EMainRoutes.CATALOG}` : `/${EMainRoutes.CHANNELS}/${EMainRoutes.CREATE}`}
							onClick={() =>
								sendYmEvent(hasChannels ? 'click_catalog' : 'click_add_channel', {
									page_screen: EYmPageScreen.FINANCE_SCREEN,
								})
							}
							block
							color="primary"
							variant="outlined">
							{hasChannels ? t('В каталог') : t('Добавить')}
						</ButtonStyleLink>
					}
				/>
			)}
			<Pagination count={data?.count} />
		</div>
	);
};
